using System;using System.IO;using System.Collections.Generic;using Por.Core;
class Exit:Exception{}
class IoHost:IGameIoHost{
 public Queue<byte> Keys=new Queue<byte>();public List<string> Events=new List<string>();public StringWriter Log;public bool OpenFail, HaltReturns;public bool KeyPressed{get{return Keys.Count>0;}}
 public byte ReadKey(){Events.Add("read");return Keys.Dequeue();}public void SoundCommand(ushort c){Events.Add("sound:"+c);}public void SoundSuspend(){Events.Add("suspend");}public void Interrupt(byte n,Types.TInterruptRegisters regs){Events.Add("bios:"+n+":"+regs.ax);}public void Halt(int code){Events.Add("halt:"+code);if(!HaltReturns)throw new Exit();}public void WriteLine(string s){Events.Add("line:"+s);}public TextWriter OpenDebugLog(string path){Events.Add("open:"+path);if(OpenFail)throw new IOException("test");return Log=new StringWriter();}
}
class IoTests{
 static int checks;static IoHost h;static void Yes(bool x,string s){checks++;if(!x)throw new Exception(s);}static void Reset(){h=new IoHost();GameIo.Host=h;GameIo.saveSettings=null;GameIo.showMemory=null;GDVars.stingArg=false;GDVars.stingHpFlag=0;GDVars.debugTraceEnabled=false;GDVars.debugFile=null;GDVars.sound.mode=0;GDVars.soundMode=0;GDVars.soundSaved=2;GDVars.soundOn=0;}
 static void Keys(){for(int key=0;key<256;key++){Reset();h.Keys.Enqueue((byte)key);h.Keys.Enqueue(19);h.Keys.Enqueue(4);int settings=0;GameIo.saveSettings=()=>settings++;byte result=GameIo.ReadGameKey();Yes(result==(key==0?0:4),"drain returns last byte");Yes(h.Keys.Count==(key==0?2:0),"extended leaves scan pending");Yes(settings==(key==19?1:0),"controls first byte only");Yes(GDVars.stingHpFlag==0,"tail controls ignored");}
 Reset();h.Keys.Enqueue(0);h.Keys.Enqueue(19);GameIo.DiscardPendingKeys();Yes(h.Keys.Count==0&&GDVars.soundMode==0,"discard extended scan not ctrlS");GameIo.DiscardPendingKeys();Yes(h.Events.Count==2,"empty discard no read");Reset();h.Keys.Enqueue(19);h.Keys.Enqueue(65);int n=0;GameIo.saveSettings=()=>n++;GameIo.DiscardPendingKeys();Yes(h.Keys.Count==0&&n==1,"discard processes first control");}
 static void Sound(){for(int device=0;device<4;device++)for(int mode=0;mode<4;mode++)for(int on=0;on<2;on++){Reset();GDVars.sound.mode=(byte)device;GDVars.soundMode=(byte)mode;GDVars.soundSaved=2;GDVars.soundOn=7;GameIo.SetSound(on!=0);if(device==C_Sound.MODE_DISABLED)Yes(GDVars.soundMode==mode&&GDVars.soundOn==7&&h.Events.Count==0,"no sound device no effect");else{Yes(GDVars.soundOn==on,"setting tracks request");Yes(GDVars.soundMode==(on==0?C_Sound.MODE_DISABLED:mode==C_Sound.MODE_DISABLED?2:mode),"mode toggle");bool stop=on==0&&mode!=C_Sound.MODE_DISABLED,suspend=on!=0&&mode==C_Sound.MODE_DISABLED;Yes(h.Events.Count==(stop||suspend?1:0),"no repeated commands");if(stop)Yes(h.Events[0]=="sound:"+GDConsts.soundIds.commands[0],"stop command");if(suspend)Yes(h.Events[0]=="suspend","resume through suspend");}}
 Reset();GameIo.Host=null;GDVars.sound.mode=(byte)C_Sound.MODE_DISABLED;GameIo.SetSound(true);Yes(GDVars.soundOn==0,"disabled no hardware required");}
 static void DebugKeys(){Reset();GDVars.stingArg=true;for(int n=0;n<3;n++){h.Keys.Enqueue(4);GameIo.ReadGameKey();Yes(GDVars.stingHpFlag==(n%2==0?1:0),"sting hp toggles");}h.Keys.Enqueue(12);GameIo.ReadGameKey();Yes(GDVars.debugTraceEnabled&&h.Events.Contains("open:debug.txt"),"trace opens truncate writer");var a=new Types.TCharRecord();a.name="ALICE";a.effectsAddr=new Types.TEffectRec{id=7,next=new Types.TEffectRec{id=255}};a.nextCharAddr=new Types.TCharRecord();a.nextCharAddr.name="BOB";a.nextCharAddr.effectsAddr=new Types.TEffectRec{id=1};GDVars.creatureList=a;h.Keys.Enqueue(26);GameIo.ReadGameKey();Yes(h.Log.ToString()=="who: ALICE  sp#: 7"+Environment.NewLine+"who: ALICE  sp#: 255"+Environment.NewLine+"who: BOB  sp#: 1"+Environment.NewLine,"effect linked list dump");h.Keys.Enqueue(12);GameIo.ReadGameKey();Yes(!GDVars.debugTraceEnabled,"trace toggle off");Reset();GDVars.stingArg=true;h.OpenFail=true;h.Keys.Enqueue(12);GameIo.ReadGameKey();Yes(!GDVars.debugTraceEnabled,"source IOResult disables trace on failed open");Reset();GDVars.stingArg=true;int calls=0;GameIo.showMemory=()=>{calls++;h.Keys.Enqueue(25);GameIo.ReadGameKey();};h.Keys.Enqueue(25);GameIo.ReadGameKey();Yes(calls==1,"memory hook recursion guarded");h.Keys.Enqueue(25);GameIo.ReadGameKey();Yes(calls==2,"memory guard reset");}
 static void Boundaries(){Reset();h.HaltReturns=true;bool failed=false;try{GameIo.ExitGame();}catch(InvalidOperationException){failed=true;}Yes(failed,"returning host Halt fails closed");Reset();GDVars.stingArg=true;GameIo.showMemory=()=>{throw new IOException("hook");};h.Keys.Enqueue(25);try{GameIo.ReadGameKey();}catch(IOException){}int calls=0;GameIo.showMemory=()=>calls++;h.Keys.Enqueue(25);GameIo.ReadGameKey();Yes(calls==1,"throwing memory hook guard reset");}
 static void Main(){Boundaries();Keys();Sound();DebugKeys();Reset();GDVars.savedVideoMode=3;h.Keys.Enqueue(65);try{GameIo.FatalError("failure");throw new Exception("fatal returned");}catch(Exit){}Yes(string.Join("|",h.Events)=="bios:16:3|line:failure|read|sound:"+GDConsts.soundIds.commands[0]+"|bios:16:3|halt:0","fatal BIOS order direct saved mode");Yes(GDVars.soundMode==GDVars.soundSaved,"exit restores sound");Reset();GDVars.stingArg=true;h.Keys.Enqueue(3);try{GameIo.ReadGameKey();throw new Exception("ctrlC returned");}catch(Exit){}Yes(h.Events.Contains("halt:0"),"STING ctrlC exits");GameIo.Host=null;bool failed=false;try{GameIo.ReadGameKey();}catch(NotSupportedException){failed=true;}Yes(failed,"missing host fails closed");Console.WriteLine("GameIo source-derived assertions: "+checks);}
}
